from produire import produire
from format_lecon import paras,table,steps
parts=[
('La {déviation de la cloison nasale est une anomalie de l’axe du septum}. Elle peut gêner le passage de l’air. Elle n’est pathologique que dans son contexte fonctionnel.',paras('La cloison sépare les deux fosses nasales et comporte cartilage et os. Une déviation peut réduire le calibre d’un côté ou des deux, avec d’autres facteurs comme les cornets.', 'Les HUG rappellent que les déviations sont fréquentes et souvent asymptomatiques. Trouver une cloison déviée chez un ronfleur ne prouve donc pas une causalité exclusive.')),
('Le {contexte peut être développemental ou traumatique}. La croissance naturelle du nez et les traumatismes expliquent de nombreuses déviations. L’histoire des symptômes guide la pertinence du constat.',paras('Distinguer une gêne ancienne stable d’une obstruction apparue récemment. Une chirurgie préalable, une rhinite ou une utilisation prolongée de décongestionnant peuvent modifier la respiration.', 'La Société suisse ORL décrit une association possible avec ronflement ou sinusites répétées. Ce lien n’autorise pas à promettre une guérison des apnées par la seule septoplastie.')),
('La {résistance nasale dépend du calibre et de la muqueuse}. Une déviation fixe peut être aggravée par un œdème variable. Le pharynx reste un autre niveau possible d’obstruction.',paras('L’écoulement de l’air dépend de plusieurs structures, notamment cloison, cornets et région valvaire. Un traitement anti-inflammatoire peut diminuer la composante muqueuse mais ne redresse pas le cartilage.', 'La respiration buccale nocturne et l’inconfort sous masque peuvent en résulter. Une chirurgie nasale peut faciliter la tolérance de la pression positive sans nécessairement normaliser les événements pharyngés.')),
('Les {alarmes excluent une simple déviation chronique}. Après traumatisme, une obstruction rapidement douloureuse peut évoquer un hématome septal. Des signes orbitaires ou neurologiques demandent une évaluation urgente.',paras('Un hématome septal doit être recherché et pris en charge rapidement par l’équipe compétente. Une obstruction progressive d’un seul côté avec saignements ne doit pas être attribuée automatiquement à une ancienne déviation.', 'Les pauses et la somnolence dangereuse suivent leur propre parcours. Une anomalie nasale visible ne diminue pas le risque d’endormissement au volant.')),
('L’{anamnèse précise côté, variabilité et retentissement}. Demander traumatisme, gêne à l’effort, sommeil et infections. Rechercher une composante allergique ou médicamenteuse.',paras('Comparer respiration diurne et nocturne, caractère constant ou alternant, diminution de l’odorat et écoulement. Noter traitement essayé, durée et réponse.', 'Si la personne utilise une pression positive, identifier masque, fuites, congestion et difficultés pratiques. La décision opératoire doit répondre à une gêne définie, pas à une photographie seule.')),
('L’{examen nasal vérifie la concordance anatomofonctionnelle}. Inspection et rhinoscopie évaluent cloison, cornets et muqueuse. L’endoscopie complète selon les symptômes.',paras('Le spécialiste recherche d’autres obstacles, une masse ou une pathologie inflammatoire. L’examen de la bouche, de la mandibule et du pharynx reste pertinent chez un ronfleur.', 'Une amélioration de la congestion ne prouve pas la disparition d’un obstacle fixe. À l’inverse, une déviation visible peut avoir peu de retentissement.')),
('L’{approche syndromique sépare obstacle fixe et inflammation}. Les deux peuvent coexister. Les symptômes inhabituels imposent un diagnostic alternatif.',table(['Présentation','Orientation'],[['Obstruction ancienne et déviation concordante.','Cause septale possible.'],['Prurit, éternuements, variabilité avec exposition.','Rhinite associée.'],['Anosmie et formations bilatérales.','Polypose possible.'],['Obstruction récente, sang ou masse.','Rechercher une autre lésion.'] ])),
('Le {diagnostic exige une gêne compatible avec l’examen}. La déviation anatomique seule ne suffit pas à indiquer une opération. L’objectif thérapeutique doit être explicite.',paras('Les HUG proposent une discussion selon gêne, gravité, importance de la déviation, bénéfices et risques. Une intolérance à la pression positive peut constituer un motif d’évaluation.', 'La confirmation d’un syndrome d’apnées repose sur une étude du sommeil. Une septoplastie et un traitement d’apnées ne sont pas des interventions interchangeables.')),
('Les {examens complémentaires sont choisis par le spécialiste}. Une endoscopie peut préciser un obstacle postérieur. L’imagerie n’est pas systématique pour toute déviation isolée.',paras('Un scanner se discute selon suspicion de maladie sinusienne, lésion ou planification complexe. L’exploration doit répondre à une question précise.', 'En présence de pauses, étouffements ou somnolence, le bilan du sommeil se poursuit indépendamment du bilan nasal. Un enregistrement peut aussi être utile pour vérifier une réponse thérapeutique selon l’indication.')),
('L’{algorithme vérifie d’abord les causes réversibles et les alarmes}. Une intervention se discute après évaluation de la gêne. Le suivi porte sur respiration nasale et sommeil.',steps('Rechercher traumatisme récent compliqué ou lésion suspecte.', 'Évaluer déviation, muqueuse, cornets et autres obstacles.', 'Traiter une inflammation associée selon son indication.', 'Si gêne persistante concordante, discuter septoplastie et risques avec l’ORL.', 'Réévaluer le nez et maintenir le traitement du sommeil tant que son indication persiste.')),
('La {prise en charge suisse peut être médicale pour la composante muqueuse et chirurgicale pour l’obstacle fixe}. Une septoplastie vise à améliorer la respiration nasale. Elle n’est pas un traitement automatique du ronflement.',paras('Aucun médicament ne redresse la cloison. Si une rhinite associée est démontrée, son traitement peut réduire la gêne ; les doses relèvent de la monographie correspondante et de la spécialité.', 'La septoplastie peut s’associer à une réduction des cornets selon l’examen. Expliquer saignement, infection, hématome, perforation, modifications de sensibilité ou de forme, et possibilité de résultat incomplet.', 'Les recommandations suisses indiquent qu’une meilleure respiration nasale peut rendre possible le port d’un masque nasal. Une chirurgie nasale ne dispense pas de contrôler les apnées ni d’évaluer les autres étages.')),
('Le {suivi contrôle cicatrisation et efficacité fonctionnelle}. Respecter les consignes opératoires personnalisées. Un saignement important, une fièvre ou une douleur croissante justifient un contact rapide.',paras('La fiche de la Société suisse ORL recommande notamment de ne pas se moucher pendant au moins une semaine après intervention ; le chirurgien adapte les soins et le calendrier de retrait du matériel.', 'Des croûtes et un gonflement peuvent gêner transitoirement. Une obstruction durable ou récidivante doit être réévaluée sans conclure automatiquement à une nouvelle déviation.')),
('Le {point clé est de traiter une gêne documentée}. La concordance entre symptômes et anatomie conditionne le bénéfice attendu. Le bruit et les apnées restent des critères distincts.',paras('Une respiration nasale améliorée peut faciliter le traitement du sommeil. Elle ne constitue pas à elle seule une preuve de guérison respiratoire nocturne.'))]
quiz=[('Toute déviation est-elle symptomatique ?','Non.'),('Un spray redresse-t-il le cartilage ?','Non.'),('Une rhinite peut-elle aggraver la gêne ?','Oui.'),('Quel diagnostic urgent rechercher après traumatisme avec obstruction douloureuse ?','Un hématome septal.'),('Un saignement unilatéral persistant est-il expliqué par défaut par la déviation ?','Non.'),('Le scanner est-il systématique ?','Non.'),('Quel est l’objectif principal d’une septoplastie ?','Améliorer une respiration nasale gênée par une déviation concordante.'),('La chirurgie garantit-elle un succès complet ?','Non.'),('Peut-elle faciliter un masque nasal ?','Oui, dans des situations sélectionnées.'),('Peut-on arrêter automatiquement la pression positive après l’opération ?','Non.'),('Les cornets doivent-ils être évalués ?','Oui.'),('Une perforation septale est-elle une complication possible ?','Oui.'),('La fiche suisse conseille-t-elle de se moucher immédiatement ?','Non, elle recommande au moins une semaine sans mouchage.'),('L’amélioration du bruit suffit-elle à conclure sur les apnées ?','Non.')]
produire(5,parts,quiz,(1,3,6,8,10,11))
